export default async function query(_x, ctx) {
  let s = await ctx.state.get("zendesk-owner-cursor");
  if (!s) {
    const now = Math.floor(Date.now() / 1000);
    s = { since: now, startTime: now - 120, cursor: null };
    await ctx.state.set("zendesk-owner-cursor", s);
  }
  return {
    query: s.cursor
      ? { cursor: s.cursor, per_page: 100 }
      : { start_time: s.startTime, per_page: 100 },
  };
}

