export default async function next({ page, previous }, ctx) {
  if (
    !Array.isArray(page?.tickets) ||
    typeof page.after_cursor !== "string" ||
    typeof page.end_of_stream !== "boolean"
  )
    throw Error("Invalid export page");
  let s = await ctx.state.get("zendesk-owner-cursor");
  const pageKey = s.cursor ?? String(s.startTime);
  let i = previous?.pageKey === pageKey ? previous.index : 0;
  while (i < page.tickets.length) {
    const t = page.tickets[i++];
    if (
      !Number.isSafeInteger(t.id) ||
      !Number.isSafeInteger(t.requester_id) ||
      !Number.isFinite(Date.parse(t.created_at))
    )
      throw Error("Invalid ticket");
    if (Date.parse(t.created_at) < s.since * 1000) continue;
    const key = "zendesk-owner-ticket:" + t.id,
      old = await ctx.state.get(key);
    if (old?.status === "done") continue;
    return {
      state: { index: i, pageKey },
      more: true,
      fetchNext: false,
      ticketId: t.id,
      userId: t.requester_id,
      key,
    };
  }
  if (!page.end_of_stream && page.after_cursor === s.cursor) throw Error("Repeated export cursor");
  s.cursor = page.after_cursor;
  await ctx.state.set("zendesk-owner-cursor", s);
  return {
    state: { index: i, pageKey },
    more: false,
    fetchNext: !page.end_of_stream,
    ticketId: 1,
    userId: 1,
    key: "",
  };
}

