export default function person({ items, nextCursor, email }) {
  if (nextCursor || items.length > 1) throw Error("Ambiguous Pipedrive person");
  if (!items.length) return { found: false, ownerId: 1 };
  const p = items[0].item;
  if (
    !p?.emails?.some((x) => x.toLowerCase() === email.toLowerCase()) ||
    !Number.isSafeInteger(p.owner?.id)
  )
    throw Error("Invalid Pipedrive person match");
  return { found: true, ownerId: p.owner.id };
}

