export default function agent({ users, email, nextPage }) {
  if (nextPage) throw Error("Agent search has another page");
  const u = users.filter(
    (x) =>
      x.email?.toLowerCase() === email.toLowerCase() &&
      ["agent", "admin"].includes(x.role) &&
      x.active !== false,
  );
  if (u.length > 1) throw Error("Ambiguous Zendesk agent");
  return { found: u.length === 1, agentId: u[0]?.id ?? 1 };
}

